    (N'00000000-0000-4000-8000-00000000009b', N'00000000-0000-4000-8000-000000000001', N'SQL connection pool exhaustion on claims-api', N'claims-api 5xx rate rising, p95 latency above 3 s, SQLTransientConnectionException connection is not available, SQL sessions percent above 90, HikariCP pending threads', N'1. Confirm: in Application Insights check `AppExceptions` for `SQLTransientConnectionException` and SQL `sessions_percent`.
2. Identify long-running queries: `SELECT TOP 10 * FROM sys.dm_exec_requests ORDER BY total_elapsed_time DESC`.
3. Mitigate: `kubectl -n claims rollout restart deploy/claims-api` one pod at a time.
4. If a recent deployment is the cause, `helm rollback claims-api <previous revision>`.
5. Verify: 5xx rate below 1% and SQL sessions below 60% for 15 minutes.
6. Escalate to the DBA team if blocking sessions persist.', NULL, N'["00000000-0000-4000-8000-000000000006", "00000000-0000-4000-8000-000000000015"]', NULL, N'{"sql": 6, "connection": 7, "pool": 2, "exhaustion": 2, "claims-api": 6, "claims": 7, "api": 6, "5xx": 3, "rate": 3, "rising": 2, "p95": 2, "latency": 2, "above": 4, "sqltransient": 3, "exception": 3, "available": 2, "sessions": 5, "percent": 3, "90": 2, "hikari": 2, "cp": 2, "pending": 2, "threads": 2, "confirm": 1, "application": 1, "insights": 1, "check": 1, "app": 1, "exceptions": 1, "sessions_percent": 1, "identify": 1, "long-running": 1, "long": 1, "running": 1, "queries": 1, "select": 1, "top": 1, "10": 1, "sys.dm_exec_requests": 1, "sys": 1, "dm": 1, "exec": 1, "requests": 1, "order": 1, "total_elapsed_time": 1, "total": 1, "elapsed": 1, "time": 2, "desc": 1, "mitigate": 1, "kubectl": 1, "rollout": 1, "restart": 1, "deploy": 1, "one": 1, "pod": 1, "if": 2, "recent": 1, "deployment": 1, "cause": 1, "helm": 1, "rollback": 1, "previous": 1, "revision": 1, "verify": 1, "below": 2, "60": 1, "15": 1, "minutes": 1, "escalate": 1, "dba": 1, "team": 1, "blocking": 1, "persist": 1}', 1, '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', N'system:seed', N'system:seed'),
    (N'00000000-0000-4000-8000-00000000009c', N'00000000-0000-4000-8000-000000000001', N'claims-document-renderer OOMKilled restarts', N'claims-document-renderer pod restarts, OOMKilled, exit code 137, memory working set above 90 percent, letters not generated', N'1. Confirm `OOMKilled` in `kubectl -n claims-docs describe pod <pod>`.
2. Restart the deployment: `kubectl -n claims-docs rollout restart deploy/claims-document-renderer`.
3. Reduce pressure: `kubectl -n claims-docs set env deploy/claims-document-renderer RENDER_MAX_PAGES=3`.
4. Verify memory growth is flat for 30 minutes. Raise a defect for the page pool leak.', NULL, N'["00000000-0000-4000-8000-000000000009"]', NULL, N'{"claims-document-renderer": 6, "claims": 9, "document": 6, "renderer": 6, "oomkilled": 5, "restarts": 4, "pod": 4, "exit": 2, "code": 2, "137": 2, "memory": 3, "working": 2, "set": 3, "above": 2, "90": 2, "percent": 2, "letters": 2, "generated": 2, "confirm": 1, "kubectl": 3, "claims-docs": 3, "docs": 3, "describe": 1, "restart": 2, "deployment": 1, "rollout": 1, "deploy": 2, "reduce": 1, "pressure": 1, "env": 1, "render_max_pages": 1, "render": 1, "max": 1, "pages": 1, "verify": 1, "growth": 1, "flat": 1, "30": 1, "minutes": 1, "raise": 1, "defect": 1, "page": 1, "pool": 1, "leak": 1}', 1, '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', N'system:seed', N'system:seed'),
    (N'00000000-0000-4000-8000-00000000009d', N'00000000-0000-4000-8000-000000000001', N'API gateway throttling (429) on claims-apim', N'APIM 429 responses, Too Many Requests, rate limit exceeded, spike in portal traffic', N'1. Check the `Requests` metric split by response code on claims-apim.
2. Identify the caller from the `ApiManagementGatewayLogs` table.
3. Raise the product rate limit policy temporarily (change request required for prod) or ask the caller to back off.
4. Notify business owners if customers are affected.', NULL, N'["00000000-0000-4000-8000-000000000005"]', NULL, N'{"api": 3, "gateway": 3, "throttling": 2, "429": 4, "claims-apim": 3, "claims": 3, "apim": 5, "responses": 2, "too": 2, "many": 2, "requests": 3, "rate": 3, "limit": 3, "exceeded": 2, "spike": 2, "portal": 2, "traffic": 2, "check": 1, "metric": 1, "split": 1, "response": 1, "code": 1, "identify": 1, "caller": 2, "management": 1, "logs": 1, "table": 1, "raise": 1, "product": 1, "policy": 1, "temporarily": 1, "change": 1, "request": 1, "required": 1, "prod": 1, "ask": 1, "back": 1, "off": 1, "notify": 1, "business": 1, "owners": 1, "if": 1, "customers": 1, "affected": 1}', 0, NULL, '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', N'system:seed', N'system:seed'),
    (N'00000000-0000-4000-8000-00000000009e', N'00000000-0000-4000-8000-000000000026', N'Partner mTLS client certificate rotation', N'quote endpoint 502, UNABLE_TO_VERIFY_LEAF_SIGNATURE, certificate has expired, tls.error in Elastic, channel API availability dropping', N'1. Check expiry: `az keyvault certificate show --vault-name kv-chad-prd --name chad-partner-client --query attributes.expires`.
2. Import the renewed certificate into Key Vault (certificate team provides the PFX).
3. Restart: `kubectl -n channel-apis rollout restart deploy/quote-service`.
4. Verify a test quote returns 200 and `tls.error` disappears from Elastic.', NULL, N'["00000000-0000-4000-8000-00000000002c", "00000000-0000-4000-8000-00000000002b"]', NULL, N'{"partner": 3, "tls": 5, "client": 3, "certificate": 7, "rotation": 2, "quote": 4, "endpoint": 2, "502": 2, "unable_to_verify_leaf_signature": 2, "unable": 2, "verify": 3, "leaf": 2, "signature": 2, "expired": 2, "tls.error": 3, "error": 3, "elastic": 3, "channel": 3, "api": 2, "availability": 2, "dropping": 2, "check": 1, "expiry": 1, "az": 1, "keyvault": 1, "show": 1, "vault-name": 1, "vault": 2, "name": 2, "kv-chad-prd": 1, "kv": 1, "chad": 2, "prd": 1, "chad-partner-client": 1, "query": 1, "attributes.expires": 1, "attributes": 1, "expires": 1, "import": 1, "renewed": 1, "key": 1, "team": 1, "provides": 1, "pfx": 1, "restart": 2, "kubectl": 1, "channel-apis": 1, "apis": 1, "rollout": 1, "deploy": 1, "quote-service": 1, "service": 1, "test": 1, "returns": 1, "200": 1, "disappears": 1}', 0, NULL, '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', N'system:seed', N'system:seed'),
    (N'00000000-0000-4000-8000-00000000009f', N'00000000-0000-4000-8000-000000000026', N'APIM throttling during campaigns', N'chad-apim 429, rate limit, traffic spike, marketing campaign, error budget burning', N'1. Confirm the 429 share on chad-apim and the calling subscription key.
2. Agree a temporary limit increase with the API owner.
3. Scale the `channel-apis` deployments if backend latency is also rising.', NULL, N'["00000000-0000-4000-8000-00000000002b"]', NULL, N'{"apim": 5, "throttling": 2, "during": 2, "campaigns": 2, "chad-apim": 3, "chad": 3, "429": 3, "rate": 2, "limit": 3, "traffic": 2, "spike": 2, "marketing": 2, "campaign": 2, "error": 2, "budget": 2, "burning": 2, "confirm": 1, "share": 1, "calling": 1, "subscription": 1, "key": 1, "agree": 1, "temporary": 1, "increase": 1, "api": 1, "owner": 1, "scale": 1, "channel-apis": 1, "channel": 1, "apis": 1, "deployments": 1, "if": 1, "backend": 1, "latency": 1, "rising": 1}', 2, '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', N'system:seed', N'system:seed'),
    (N'00000000-0000-4000-8000-0000000000a0', N'00000000-0000-4000-8000-00000000003e', N'Partner bank timeouts', N'payment-api latency, payments stuck PENDING, partner bank timeout, PartnerBankCall duration above 10 seconds, retries amplifying load', N'1. Check `PartnerBankCall` p95 and `partnerStatus` in Application Insights.
2. Set `payments.retry.enabled=false` to stop retry amplification.
3. Contact the partner bank operations desk (number in the support contacts page) and share the failing request ids.
4. After recovery, re-enable retries and replay stuck payments with the reconciliation job.', NULL, N'["00000000-0000-4000-8000-000000000043", "00000000-0000-4000-8000-000000000047"]', NULL, N'{"partner": 9, "bank": 8, "timeouts": 2, "payment-api": 2, "payment": 2, "api": 2, "latency": 2, "payments": 4, "stuck": 3, "pending": 2, "timeout": 2, "call": 3, "duration": 2, "above": 2, "10": 2, "seconds": 2, "retries": 3, "amplifying": 2, "load": 2, "check": 1, "p95": 1, "status": 1, "application": 1, "insights": 1, "set": 1, "payments.retry.enabled": 1, "retry": 2, "enabled": 1, "false": 1, "stop": 1, "amplification": 1, "contact": 1, "operations": 1, "desk": 1, "number": 1, "support": 1, "contacts": 1, "page": 1, "share": 1, "failing": 1, "request": 1, "ids": 1, "after": 1, "recovery": 1, "re-enable": 1, "re": 1, "enable": 1, "replay": 1, "reconciliation": 1, "job": 1}', 1, '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', N'system:seed', N'system:seed'),
    (N'00000000-0000-4000-8000-0000000000a1', N'00000000-0000-4000-8000-000000000058', N'PBIL0400 abend S0C7 restart', N'PBIL0400 abend, S0C7 data exception, premium billing batch failed, IEF450I', N'1. Read the abend in SDSF: job PBIL0400 step name and failing program.
2. S0C7 means invalid packed data. Identify the bad record from the dump with the application support analyst.
3. Fix or skip the record, then restart from the failed step using the restart JCL (`RESTART=STEP0400`).
4. Verify downstream job PBIL0500 starts and the billing window is met.', NULL, N'["00000000-0000-4000-8000-00000000005c"]', NULL, N'{"pbil0400": 5, "abend": 5, "s0c7": 5, "restart": 5, "data": 3, "exception": 2, "premium": 2, "billing": 3, "batch": 2, "failed": 3, "ief450i": 2, "read": 1, "sdsf": 1, "job": 2, "step": 2, "name": 1, "failing": 1, "program": 1, "means": 1, "invalid": 1, "packed": 1, "identify": 1, "bad": 1, "record": 2, "dump": 1, "application": 1, "support": 1, "analyst": 1, "fix": 1, "skip": 1, "using": 1, "jcl": 1, "step0400": 1, "verify": 1, "downstream": 1, "pbil0500": 1, "starts": 1, "window": 1, "met": 1}', 1, '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', N'system:seed', N'system:seed'),
    (N'00000000-0000-4000-8000-0000000000a2', N'00000000-0000-4000-8000-000000000062', N'SaaS vendor outage communications', N'benefits portal unavailable, synthetic probe failing, vendor status page degraded, BenefitsCloud incident', N'1. Confirm the outage on the vendor status page and with the synthetic probe.
2. Open a priority ticket with the vendor support contact and note the ticket number.
3. Notify HR operations and employee communications with the approved holding statement.
4. Post an update every 30 minutes until the vendor confirms recovery, then verify the probe is green for 15 minutes.', NULL, N'["00000000-0000-4000-8000-000000000065"]', NULL, N'{"saa": 2, "vendor": 7, "outage": 3, "communications": 3, "benefits": 4, "portal": 2, "unavailable": 2, "synthetic": 3, "probe": 4, "failing": 2, "status": 3, "page": 3, "degraded": 2, "cloud": 2, "incident": 2, "confirm": 1, "open": 1, "priority": 1, "ticket": 2, "support": 1, "contact": 1, "note": 1, "number": 1, "notify": 1, "hr": 1, "operations": 1, "employee": 1, "approved": 1, "holding": 1, "statement": 1, "post": 1, "update": 1, "every": 1, "30": 1, "minutes": 2, "until": 1, "confirms": 1, "recovery": 1, "verify": 1, "green": 1, "15": 1}', 1, '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', N'system:seed', N'system:seed');
